 IF (SELECT coalesce(jsonb_agg(jsonb_build_object(
 'evtname',e.evtname,'evtevent',e.evtevent,'evtenabled',e.evtenabled,'evttags',e.evttags,
 'trigger_owner',pg_catalog.pg_get_userbyid(e.evtowner),'function_schema',n.nspname,'function_name',p.proname,
 'function_owner',pg_catalog.pg_get_userbyid(p.proowner),'prosecdef',p.prosecdef,'proconfig',p.proconfig,
 'proacl',p.proacl::text,'definition',pg_catalog.pg_get_functiondef(p.oid)) ORDER BY e.evtname),'[]'::jsonb)
 FROM pg_catalog.pg_event_trigger e JOIN pg_catalog.pg_proc p ON p.oid=e.evtfoid JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace
 WHERE e.evtenabled<>'D') IS DISTINCT FROM $reviewed_triggers$[{"evtname":"issue_graphql_placeholder","evtevent":"sql_drop","evtenabled":"O","evttags":["DROP EXTENSION"],"trigger_owner":"supabase_admin","function_schema":"extensions","function_name":"set_graphql_placeholder","function_owner":"supabase_admin","prosecdef":false,"proconfig":["search_path=\"\""],"proacl":"{=X/supabase_admin,supabase_admin=X/supabase_admin,postgres=X*/supabase_admin}","definition":"CREATE OR REPLACE FUNCTION extensions.set_graphql_placeholder()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\n    DECLARE\n    graphql_is_dropped bool;\n    BEGIN\n    graphql_is_dropped = (\n        SELECT ev.schema_name = 'graphql_public'\n        FROM pg_event_trigger_dropped_objects() AS ev\n        WHERE ev.schema_name = 'graphql_public'\n    );\n\n    IF graphql_is_dropped\n    THEN\n        create or replace function graphql_public.graphql(\n            \"operationName\" text default null,\n            query text default null,\n            variables jsonb default null,\n            extensions jsonb default null\n        )\n            returns jsonb\n            language plpgsql\n            set search_path to ''\n        as $$\n            DECLARE\n                server_version float;\n            BEGIN\n                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);\n\n                IF server_version >= 14 THEN\n                    RETURN jsonb_build_object(\n                        'errors', jsonb_build_array(\n                            jsonb_build_object(\n                                'message', 'pg_graphql extension is not enabled.'\n                            )\n                        )\n                    );\n                ELSE\n                    RETURN jsonb_build_object(\n                        'errors', jsonb_build_array(\n                            jsonb_build_object(\n                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'\n                            )\n                        )\n                    );\n                END IF;\n            END;\n        $$;\n    END IF;\n\n    END;\n$function$\n"},{"evtname":"issue_pg_cron_access","evtevent":"ddl_command_end","evtenabled":"O","evttags":["CREATE EXTENSION"],"trigger_owner":"supabase_admin","function_schema":"extensions","function_name":"grant_pg_cron_access","function_owner":"supabase_admin","prosecdef":false,"proconfig":["search_path=\"\""],"proacl":"{=X/supabase_admin,supabase_admin=X*/supabase_admin,dashboard_user=X/supabase_admin}","definition":"CREATE OR REPLACE FUNCTION extensions.grant_pg_cron_access()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nBEGIN\n  IF EXISTS (\n    SELECT\n    FROM pg_event_trigger_ddl_commands() AS ev\n    JOIN pg_extension AS ext\n    ON ev.objid = ext.oid\n    WHERE ext.extname = 'pg_cron'\n  )\n  THEN\n    grant usage on schema cron to postgres with grant option;\n\n    alter default privileges in schema cron grant all on tables to postgres with grant option;\n    alter default privileges in schema cron grant all on functions to postgres with grant option;\n    alter default privileges in schema cron grant all on sequences to postgres with grant option;\n\n    alter default privileges for user supabase_admin in schema cron grant all\n        on sequences to postgres with grant option;\n    alter default privileges for user supabase_admin in schema cron grant all\n        on tables to postgres with grant option;\n    alter default privileges for user supabase_admin in schema cron grant all\n        on functions to postgres with grant option;\n\n    grant all privileges on all tables in schema cron to postgres with grant option;\n    revoke all on table cron.job from postgres;\n    grant select on table cron.job to postgres with grant option;\n    revoke trigger on cron.job_run_details from postgres;\n  END IF;\nEND;\n$function$\n"},{"evtname":"issue_pg_graphql_access","evtevent":"ddl_command_end","evtenabled":"O","evttags":["CREATE FUNCTION"],"trigger_owner":"supabase_admin","function_schema":"extensions","function_name":"grant_pg_graphql_access","function_owner":"supabase_admin","prosecdef":false,"proconfig":["search_path=\"\""],"proacl":"{=X/supabase_admin,supabase_admin=X/supabase_admin,postgres=X*/supabase_admin}","definition":"CREATE OR REPLACE FUNCTION extensions.grant_pg_graphql_access()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nbegin\n    if not exists (\n        select 1\n        from pg_catalog.pg_event_trigger_ddl_commands() ev\n        join pg_catalog.pg_extension e on ev.objid = e.oid\n        where e.extname = 'pg_graphql'\n    ) then\n        return;\n    end if;\n\n    drop function if exists graphql_public.graphql;\n    create or replace function graphql_public.graphql(\n        \"operationName\" text default null,\n        query text default null,\n        variables jsonb default null,\n        extensions jsonb default null\n    )\n        returns jsonb\n        language sql\n    as $$\n        select graphql.resolve(\n            query := query,\n            variables := coalesce(variables, '{}'),\n            \"operationName\" := \"operationName\",\n            extensions := extensions\n        );\n    $$;\n\n    -- Attach the wrapper to the extension so DROP EXTENSION cascades to it,\n    -- which in turn triggers set_graphql_placeholder to reinstall the \"not enabled\" stub.\n    alter extension pg_graphql add function graphql_public.graphql(text, text, jsonb, jsonb);\n\n    grant usage on schema graphql to postgres, anon, authenticated, service_role;\n    grant execute on function graphql.resolve to postgres, anon, authenticated, service_role;\n    grant usage on schema graphql to postgres with grant option;\n    grant usage on schema graphql_public to postgres with grant option;\nend;\n$function$\n"},{"evtname":"issue_pg_net_access","evtevent":"ddl_command_end","evtenabled":"O","evttags":["CREATE EXTENSION"],"trigger_owner":"supabase_admin","function_schema":"extensions","function_name":"grant_pg_net_access","function_owner":"supabase_admin","prosecdef":false,"proconfig":["search_path=\"\""],"proacl":"{=X/supabase_admin,supabase_admin=X*/supabase_admin,dashboard_user=X/supabase_admin}","definition":"CREATE OR REPLACE FUNCTION extensions.grant_pg_net_access()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nBEGIN\n  IF EXISTS (\n    SELECT 1\n    FROM pg_event_trigger_ddl_commands() AS ev\n    JOIN pg_extension AS ext\n    ON ev.objid = ext.oid\n    WHERE ext.extname = 'pg_net'\n  )\n  THEN\n    IF NOT EXISTS (\n      SELECT 1\n      FROM pg_roles\n      WHERE rolname = 'supabase_functions_admin'\n    )\n    THEN\n      CREATE USER supabase_functions_admin NOINHERIT CREATEROLE LOGIN NOREPLICATION;\n    END IF;\n\n    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;\n\n    IF EXISTS (\n      SELECT FROM pg_extension\n      WHERE extname = 'pg_net'\n      -- all versions in use on existing projects as of 2025-02-20\n      -- version 0.12.0 onwards don't need these applied\n      AND extversion IN ('0.2', '0.6', '0.7', '0.7.1', '0.8.0', '0.10.0', '0.11.0')\n    ) THEN\n      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;\n      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;\n\n      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;\n      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;\n\n      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;\n      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;\n\n      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;\n      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;\n    END IF;\n  END IF;\nEND;\n$function$\n"},{"evtname":"pgrst_ddl_watch","evtevent":"ddl_command_end","evtenabled":"O","evttags":null,"trigger_owner":"supabase_admin","function_schema":"extensions","function_name":"pgrst_ddl_watch","function_owner":"supabase_admin","prosecdef":false,"proconfig":["search_path=\"\""],"proacl":"{=X/supabase_admin,supabase_admin=X/supabase_admin,postgres=X*/supabase_admin}","definition":"CREATE OR REPLACE FUNCTION extensions.pgrst_ddl_watch()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE\n  cmd record;\nBEGIN\n  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()\n  LOOP\n    IF cmd.command_tag IN (\n      'CREATE SCHEMA', 'ALTER SCHEMA'\n    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'\n    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'\n    , 'CREATE VIEW', 'ALTER VIEW'\n    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'\n    , 'CREATE FUNCTION', 'ALTER FUNCTION'\n    , 'CREATE TRIGGER'\n    , 'CREATE TYPE', 'ALTER TYPE'\n    , 'CREATE RULE'\n    , 'COMMENT'\n    )\n    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp\n    AND cmd.schema_name is distinct from 'pg_temp'\n    THEN\n      NOTIFY pgrst, 'reload schema';\n    END IF;\n  END LOOP;\nEND; $function$\n"},{"evtname":"pgrst_drop_watch","evtevent":"sql_drop","evtenabled":"O","evttags":null,"trigger_owner":"supabase_admin","function_schema":"extensions","function_name":"pgrst_drop_watch","function_owner":"supabase_admin","prosecdef":false,"proconfig":["search_path=\"\""],"proacl":"{=X/supabase_admin,supabase_admin=X/supabase_admin,postgres=X*/supabase_admin}","definition":"CREATE OR REPLACE FUNCTION extensions.pgrst_drop_watch()\n RETURNS event_trigger\n LANGUAGE plpgsql\n SET search_path TO ''\nAS $function$\nDECLARE\n  obj record;\nBEGIN\n  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()\n  LOOP\n    IF obj.object_type IN (\n      'schema'\n    , 'table'\n    , 'foreign table'\n    , 'view'\n    , 'materialized view'\n    , 'function'\n    , 'trigger'\n    , 'type'\n    , 'rule'\n    )\n    AND obj.is_temporary IS false -- no pg_temp objects\n    THEN\n      NOTIFY pgrst, 'reload schema';\n    END IF;\n  END LOOP;\nEND; $function$\n"}]$reviewed_triggers$::jsonb
 THEN RAISE EXCEPTION 'reviewed_event_trigger_inventory_drift'; END IF;
 IF EXISTS(SELECT 1 FROM pg_catalog.pg_extension WHERE extname='pg_graphql') THEN RAISE EXCEPTION 'graphql_extension_requires_new_review'; END IF;
 IF (SELECT count(*) FROM pg_catalog.pg_proc p WHERE
 (p.oid='public.coach_begin_execution_v2(uuid,uuid,text,text,jsonb,uuid,boolean)'::regprocedure AND p.oid=178650
 OR p.oid='public.coach_reserve_web_v1(uuid,uuid,uuid,numeric,numeric)'::regprocedure AND p.oid=178549)
 AND pg_catalog.pg_get_userbyid(p.proowner)='postgres' AND NOT p.prosecdef
 AND p.proconfig=ARRAY['search_path=""']::text[]
 AND p.proacl::text='{postgres=X/postgres,service_role=X/postgres}'
 AND NOT pg_catalog.has_function_privilege('anon',p.oid,'EXECUTE')
 AND NOT pg_catalog.has_function_privilege('authenticated',p.oid,'EXECUTE')
 AND pg_catalog.has_function_privilege('service_role',p.oid,'EXECUTE')
 AND NOT EXISTS(SELECT 1 FROM pg_catalog.pg_depend d WHERE d.classid='pg_catalog.pg_proc'::regclass AND d.objid=p.oid AND d.refclassid='pg_catalog.pg_extension'::regclass))<>2
 THEN RAISE EXCEPTION 'coach_function_security_drift'; END IF;

END $infrastructure$;
COMMIT;
